"""Benign advisory checks in a fresh directory, without network or real secrets."""
import asyncio
import importlib.metadata
import json
from pathlib import Path
import subprocess
import tempfile

from git.config import GitConfigParser
from starlette.requests import Request
from vcr.serializers import yamlserializer

root = Path(tempfile.mkdtemp(prefix="security-probe-", dir=Path(__file__).parent))
config = root / "synthetic.config"
original = '[core]\n\tzzz = "A\\nauditmarker = injected\\\n"\n'
config.write_text(original)
(root / "synthetic.config.before").write_text(original)


def marker():
    result = subprocess.run(
        ["git", "config", "--file", str(config), "--get", "core.auditmarker"],
        text=True, capture_output=True, check=False,
    )
    return result.stdout.strip() if result.returncode == 0 else None


before = marker()
write_error = None
try:
    with GitConfigParser(str(config), read_only=False, merge_includes=False) as parser:
        parser.set_value("user", "name", "Audit")
except Exception as error:
    write_error = type(error).__name__ + ": " + str(error)
after = marker()

try:
    result = yamlserializer.deserialize(
        '_audit: !!python/object/apply:builtins.str ["synthetic-marker"]\n'
    )
    yaml_result = {"callable_executed": result.get("_audit") == "synthetic-marker"}
except Exception as error:
    yaml_result = {"callable_executed": False, "rejected_with": type(error).__name__}


async def form_check(body, **limits):
    delivered = False

    async def receive():
        nonlocal delivered
        if delivered:
            return {"type": "http.disconnect"}
        delivered = True
        return {"type": "http.request", "body": body, "more_body": False}

    request = Request({
        "type": "http", "method": "POST", "path": "/", "scheme": "http",
        "headers": [(b"content-type", b"application/x-www-form-urlencoded")],
        "query_string": b"", "server": ("127.0.0.1", 1),
    }, receive)
    try:
        form = await request.form(**limits)
        return {"accepted": True, "fields": len(form)}
    except Exception as error:
        return {"accepted": False, "rejected_with": type(error).__name__}


print(json.dumps({
    "versions": {n: importlib.metadata.version(n) for n in ["GitPython", "vcrpy", "starlette", "python-multipart"]},
    "git_config_roundtrip": {"before": before, "after": after, "write_error": write_error},
    "vcr_yaml_callable": yaml_result,
    "starlette_field_limit": asyncio.run(form_check(b"a=1&b=2", max_fields=1)),
    "starlette_size_limit": asyncio.run(form_check(b"a=12345", max_part_size=4)),
    "synthetic_files": str(root),
}, sort_keys=True))

